"""Prueba de humo de la interfaz con un navegador real (Playwright).
Uso:  python pruebas/probar_interfaz.py     (levanta su propio servidor local)
Comprueba, con clics reales y sin errores de JavaScript: pueblo vivo, fichas de rasgos, movimiento, envíos y tutorial."""
import http.server, socketserver, threading, pathlib, sys, functools
from playwright.sync_api import sync_playwright
RAIZ = pathlib.Path(__file__).resolve().parent.parent
H = functools.partial(http.server.SimpleHTTPRequestHandler, directory=str(RAIZ))
H.log_message = lambda *a, **k: None
srv = socketserver.TCPServer(('127.0.0.1', 0), H); port = srv.server_address[1]
threading.Thread(target=srv.serve_forever, daemon=True).start()
fallos = []
def ok(cond, msg):
    print(('✓ ' if cond else '✗ ') + msg)
    if not cond: fallos.append(msg)
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_page(viewport={'width': 1500, 'height': 900}); errs = []
    pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto(f'http://127.0.0.1:{port}/index.html'); pg.wait_for_timeout(500)
    pg.click('#btnStart'); pg.wait_for_timeout(1200)
    cap = pg.evaluate('myCapital()')
    pg.evaluate(f'onZone({cap}); goZone({cap},640,0)'); pg.wait_for_timeout(6000)
    acts = pg.evaluate("new Set(Object.values(LIFE.st).map(s=>s.last).filter(Boolean)).size")
    ok(pg.evaluate("document.querySelectorAll('.pp').length") > 0, 'la gente se dibuja como grupos animables')
    ok(acts >= 2, f'la gente hace actividades distintas ({acts} tipos en 6 s)')
    pg.evaluate("ui.zsub='poblacion'; renderPanel()"); pg.locator('.token[data-id]').first.hover(); pg.wait_for_timeout(300)
    ok(pg.evaluate("!!document.querySelector('#ficha.on')"), 'la ficha de rasgos aparece al pasar el mouse')
    pg.evaluate("ui.zsub='mover'; renderPanel()"); pg.locator('.ntile').first.click(); pg.locator('.stp .sb button').first.click()
    pg.click('[data-act=mvgo]'); ok(pg.evaluate("ui.orders.some(o=>o.t==='move')"), 'mover con tarjetas y botones crea la orden')
    pg.evaluate("(c)=>{ const z=G.zones[c]; G.zones[z.adj[0]].owner=0; z.food=20; ui.orders=[]; }", cap)
    pg.evaluate("ui.zsub='recursos'; renderPanel()"); pg.click('[data-act=sendgo]')
    ok(pg.evaluate("ui.orders.some(o=>o.t==='send')"), 'enviar una vez crea la orden')
    pg.locator('.sdmode button').nth(1).click(); pg.click('[data-act=sendgo]')
    ok(pg.evaluate("ui.orders.some(o=>o.t==='route')"), 'enviar cada paso crea el envío automático')
    # --- ronda 2: popup de encuentros, victoria, recursos, ofertas, escenas ---
    pg.evaluate("ui.orders=[]; G.F[0].enc={id:'refugiados',k:'oferta',who:'Unos refugiados',txt:'piden quedarse',zone:myCapital(),cost:{res:'food',n:5},gain:{units:{pob:2}},refuse:null,step:G.step}; renderPanel()"); pg.wait_for_timeout(300)
    ok(pg.evaluate("document.getElementById('dlgEnc').open"), 'un encuentro nuevo sale en ventana emergente')
    pg.click('#dlgEnc [data-act=encounter][data-v=si]')
    ok(not pg.evaluate("document.getElementById('dlgEnc').open") and pg.evaluate("ui.orders.some(o=>o.t==='encounter')"), 'al decidir, la ventana se cierra y la decisión queda en Órdenes')
    pg.evaluate("ui.tab='vic'; renderPanel()"); ok(pg.evaluate("document.querySelectorAll('.vchart .vrow').length")==7 and pg.evaluate("document.querySelectorAll('.vchart .vrow:first-child .vb').length")>=2, 'Victoria es un solo gráfico: 7 condiciones con una barra por jugador (tú y tus vecinos)')
    pg.evaluate(f"onZone({cap}); ui.zsub='mover'; renderPanel()"); ok(pg.evaluate("document.querySelectorAll('.ntile .db').length")>0, 'las zonas vecinas muestran sus recursos con insignias')
    pg.locator('.ntile .db').first.hover(); pg.wait_for_timeout(250); ok(pg.evaluate("!!document.querySelector('#ficha.on')"), 'la ficha del recurso dice qué hace')
    pg.evaluate("ui.orders=[]; ui.tab='imperio'; renderPanel()"); pg.locator('[data-act=ofopen]').first.click(); pg.locator('.ofres').nth(1).locator('button').nth(1).click(); pg.click('[data-act=ofgo]')
    ok(pg.evaluate("ui.orders.some(o=>o.t==='offer')"), 'ofrecer recursos a un rival crea la orden')
    pg.evaluate("window.__f=G.zones.find(z=>z.role==='vacia'&&z.id!==myCapital()).id; playFx([{k:'fight',zone:window.__f,facs:[0,4],losses:{0:{mil:1,civ:0},4:{mil:0,civ:0}},surprise:[],capt:{}}],null)"); pg.wait_for_timeout(1700)
    ok(pg.evaluate("Math.abs(VIEW.x+VIEW.w/2-sx(window.__f))<60"), 'la cámara visita la batalla del paso')
    pg.evaluate("G.evq=[{step:G.step,id:'prosper',dur:4}]; render()"); ok(pg.evaluate("!!document.querySelector('#evChips .eb[data-ev=prosper]')"), 'un evento que empieza aparece arriba como insignia')
    ok('año' in pg.evaluate("document.getElementById('calNote').innerText"), 'el paso muestra año y mes')
    pg.evaluate("""()=>{ const tz=G.zones.find(z=>z.owner===4); G.tributes.push({zone:tz.id,amount:8,due:G.step+4,paid:{},targets:[0],res:'food'}); ui.tab='imperio'; renderPanel(); }"""); ok(pg.evaluate("document.querySelectorAll('.reqs .ic[data-e=\"⏳\"]').length")>=1, 'el pedido de una tribu muestra cuántos pasos quedan')
    # --- ronda 3: avisos en pestañas, entrenar eligiendo, eventos como insignias, mapa de batalla ---
    pg.evaluate("ui.orders=[]; ui.trainIds=[]; renderPanel()"); ok(pg.evaluate("document.querySelectorAll('.tabal:not([hidden])').length")>0 and pg.evaluate("document.getElementById('sugBar').innerText===''"), 'las sugerencias salen como ❗ en las pestañas, no en una barra arriba')
    pg.evaluate(f"onZone({cap}); ui.form.tr_mode='civ'; ui.zsub='militar'; renderPanel()"); pg.locator('.trbest .chip').nth(1).click(); pg.click('[data-act=train]')
    ok(pg.evaluate("ui.orders.some(o=>o.t==='train'&&o.from==='civ'&&o.ids&&o.ids.length===2)"), 'nombrar generales permite elegir a quién (la orden lleva las personas)')
    pg.evaluate("ui.orders=[]; G.zones[%d].b.push({t:'cuartel',l:2,s:null,wk:0,cost:40}); G.zones[%d].prod=60; G.zones[%d].food=60; G.F[0].gold=60; ui.form.tr_mode='new'; ui.form.tr_n=1; render()" % (cap,cap,cap)); pg.locator('[data-act=trn][data-d="1"]').click(); pg.click('[data-act=train]')
    ok(pg.evaluate("ui.orders.some(o=>o.t==='train'&&o.from==='new'&&o.n===2)"), 'reclutar en el Cuartel: se elige cuántas (2 con un Cuartel de nivel 2) sin gastar civiles')
    ok(pg.evaluate("document.querySelectorAll('.trc small .rq').length")>=3, 'las tarjetas de tropa muestran producción, comida y oro')
    pg.evaluate("ui.orders=[]; ui.trainIds=[]; ui.zsub='poblacion'; renderPanel()"); pg.locator('.token[data-id]').first.click(); pg.locator('.station.mil').click()
    ok(pg.evaluate("ui.zsub==='militar'&&ui.trainIds.length===1&&ui.form.tr_mode==='civ'"), 'soltar a alguien en «Ejército» lo deja elegido para nombrarlo general en Militar')
    pg.evaluate("G.evq=[]; G.evAct=[{id:'prosper',start:G.step-2,end:G.step+9},{id:'cosecha',start:G.step-2,end:G.step+9}]; render()"); ok(pg.evaluate("document.querySelectorAll('#evChips .eb').length")==2, 'los eventos del año salen como insignias')
    pg.locator('#evChips .eb').first.hover(); pg.wait_for_timeout(250); ok(pg.evaluate("!!document.querySelector('#ficha.on .evpips')"), 'la ficha del evento muestra cuántos pasos quedan')
    pg.evaluate("""()=>{ const z=G.zones.find(z=>z.role==='vacia'&&z.id!==myCapital()); const mk=(f,t,n)=>Array.from({length:n},()=>mkUnit(G,f,t)); z.units[0]=[...mk(0,'sol',3),...mk(0,'arq',2)]; z.units[1]=[...mk(1,'sol',3),...mk(1,'arq',2)];
      resolveStep(G,[{f:0,t:'stance',target:1,stance:'alerta'}]); openBattle(G.battles.length-1); BV.k=2; renderBattle(); }""")
    ok(pg.evaluate("document.querySelectorAll('.bvsvg .bvf').length")==10, 'la batalla se ve en un campo con las tropas de cada bando')
    pg.evaluate("document.getElementById('dlgBattle').close(); G.auction={step:G.step+10,cur:'food',items:[{cat:'car',tier:0,det:{res:'prod',n:33}},{cat:'pob',tier:1,det:{}}],bids:{}}; ui.tab='recursos'; renderPanel()")
    txt = pg.evaluate("document.querySelector('.chests').innerText + ' ' + [...document.querySelectorAll('.chest')].map(c=>c.title).join(' ')")
    ok('20–40' in txt and 'no se sabe de qué recurso' in txt and 'prod' not in txt.lower().replace('producción',''), 'la subasta muestra el rango del cargamento sin revelar el recurso')
    pg.evaluate("G.auction=null; G.evAct=[{id:'inunda',start:G.step,end:G.step+5}]; render()")
    ok(pg.evaluate("document.querySelectorAll('#evChips .eb').length")>=1, 'la inundación aparece arriba como insignia del año, con los pasos que quedan')
    pg.screenshot(path='/tmp/inundacion.png'); pg.evaluate("G.evAct=[]; render()")
    pg.evaluate("ui.tab='hist'; renderPanel()")
    ok(pg.evaluate("document.querySelectorAll('[data-act=dllog]').length")==2, 'el Historial ofrece descargar el registro (.txt y .json)')
    with pg.expect_download() as dl: pg.click('[data-act=dllog][data-v=txt]')
    ruta = dl.value.path(); txt = open(ruta, encoding='utf-8').read()
    ok(dl.value.suggested_filename.endswith('.txt') and 'Condiciones de victoria' in txt and 'Historial:' in txt, 'el registro .txt se descarga con condiciones e historial')
    with pg.expect_download() as dl: pg.click('[data-act=dllog][data-v=json]')
    import json as _j; dj = _j.load(open(dl.value.path(), encoding='utf-8'))
    ok(dj['juego'] == 'Los Pasos del Imperio' and len(dj['jugadores']) >= 2 and isinstance(dj['historial'], list) and dj['telemetria'] is not None, 'el registro .json trae jugadores, historial y telemetría')
    pg.evaluate("G.over=true; G.winner=[0]; showEnd()")
    ok(pg.evaluate("document.querySelectorAll('#dlgEnd [data-act=dllog]').length")==2, 'la pantalla de fin también ofrece el registro')
    with pg.expect_download() as dl: pg.click('#dlgEnd [data-act=dllog][data-v=txt]')
    ok(dl.value.suggested_filename.endswith('.txt'), 'el botón de la pantalla de fin descarga el registro')
    pg.screenshot(path='/tmp/fin_registro.png')
    pg.evaluate("document.getElementById('dlgEnd').close(); G.over=false; ui.tab='hist'; renderPanel()"); pg.screenshot(path='/tmp/historial_registro.png')
    pg.evaluate("G.step=12; G.auction={step:20,cur:'food',items:[{cat:'car',tier:0,det:{res:'prod',n:30}},{cat:'pel',tier:2,det:{}}],bids:{}}; ui.tab='recursos'; render()")
    ok(pg.evaluate("document.querySelectorAll('.chest').length")==2 and pg.evaluate("document.querySelectorAll('.wcard').length")==12 and pg.evaluate("document.querySelectorAll('.wcard svg.wart').length")==12, 'la pestaña Recursos muestra los cofres de la subasta y las 12 maravillas con su imagen')
    ok(pg.evaluate("document.querySelectorAll('#tabBody .wok').length")>=1 and 'libre' not in pg.evaluate("document.querySelector('.wgrid').innerText").lower(), 'las maravillas disponibles llevan el ícono verde, no la palabra «libre»')
    pg.click('[data-act=bidadj][data-i="0"][data-d="5"]'); pg.click('[data-act=bidadj][data-i="0"][data-d="5"]')
    ok(pg.evaluate("document.querySelector('[data-f=bid_0]').value")=='10', 'los botones ＋ de la subasta suben la oferta de 5 en 5')
    pg.evaluate("ui.orders=[]; G.auction=null; ui.tab='imperio'; render()")
    ok(pg.evaluate("document.querySelector('#tabBody').innerText.includes('Subasta')")==False and pg.evaluate("document.querySelectorAll('#tabBody .wcard').length")==0, 'la pestaña Imperio ya no trae la subasta ni las maravillas')
    pg.evaluate("G.zones[1].owner=ME; G.zones[2].owner=ME; ui.sel=null; ui.tab='zona'; ui.zsub='edificios'; render()")
    sel=[]; pg.keyboard.press('Tab'); sel.append(pg.evaluate("ui.sel")); pg.keyboard.press('Tab'); sel.append(pg.evaluate("ui.sel")); pg.keyboard.press('Shift+Tab'); sel.append(pg.evaluate("ui.sel"))
    ok(sel==[0,1,0] and pg.evaluate("ui.zsub")=='edificios', 'Tab pasa a la siguiente zona propia (Mayús+Tab a la anterior) y conserva la subpestaña')
    pg.evaluate("G.zones[1].owner=null; G.zones[2].owner=null; ui.sel=null; render()")
    # --- cabecera del mapa, plan de red, pestañas, pedidos de tribu y deshacer (28/10/2026) ---
    pg.evaluate("G.auction=null; G.over=false; ui.tab='imperio'; ui.view='terr'; render()")
    ok(pg.evaluate("!document.getElementById('bCap')&&!document.getElementById('bAll')&&!document.getElementById('bSel')&&!document.querySelector('.toolbar')"), 'el mapa ya no tiene la barra de botones ni el texto de ayuda')
    ok(pg.evaluate("document.querySelectorAll('.vmode button').length")==2, 'los dos modos de vista son íconos en una esquina del mapa')
    ok(pg.evaluate("[...document.querySelectorAll('.tabs button')].every(b=>b.getBoundingClientRect().right<=document.querySelector('.tabs').getBoundingClientRect().right+1)"), 'las 7 pestañas caben sin quedar escondidas')
    pg.click('#vPlan'); pg.wait_for_timeout(200); v0=pg.evaluate("document.getElementById('plan').getAttribute('viewBox')")
    box=pg.locator('#vp').bounding_box(); cx=box['x']+box['width']/2; cy=box['y']+box['height']/2
    pg.mouse.move(cx,cy); pg.mouse.wheel(0,-400); pg.wait_for_timeout(150); v1=pg.evaluate("document.getElementById('plan').getAttribute('viewBox')")
    pg.mouse.move(cx,cy); pg.mouse.down(); pg.mouse.move(cx-120,cy-60,steps=5); pg.mouse.up(); pg.wait_for_timeout(150); v2=pg.evaluate("document.getElementById('plan').getAttribute('viewBox')")
    ok(float(v1.split()[2])<float(v0.split()[2]) and v2.split()[:2]!=v1.split()[:2], 'el plan de red se puede acercar con la rueda y recorrer arrastrando')
    pg.keyboard.press('Tab'); pg.wait_for_timeout(800)
    ok(float(pg.evaluate("document.getElementById('plan').getAttribute('viewBox')").split()[2])<=640, 'en el plan de red, Tab centra y acerca la zona elegida')
    pg.keyboard.press('f'); pg.wait_for_timeout(800)
    ok(float(pg.evaluate("document.getElementById('plan').getAttribute('viewBox')").split()[2])>1100, 'la tecla F muestra todo el plan')
    pg.click('#vTerr'); pg.wait_for_timeout(200)
    tz=pg.evaluate("G.zones.find(z=>z.owner===TRIBE).id")
    pg.evaluate(f"G.tributes.push({{zone:{tz},res:'food',amount:3,targets:[ME],paid:{{}},due:G.step+4}}); ui.tab='imperio'; render()")
    ok(pg.evaluate("document.querySelectorAll('.reqs .req').length")>=1, 'el pedido de la tribu aparece arriba de Imperio en una línea')
    pg.evaluate(f"ui.sel={tz}; ui.tab='zona'; ui.zsub='resumen'; render()")
    ok(pg.evaluate("document.querySelector('#tabBody').innerText.includes('Pide')")==False and pg.evaluate("document.querySelectorAll('.tribute').length")==0, 'la zona de la tribu ya no muestra el pedido')
    n0=pg.evaluate("ui.orders.length"); pg.evaluate("addOrder({t:'stance',target:1,stance:'alerta'}); render()")
    pg.keyboard.press('Control+z'); pg.wait_for_timeout(100)
    ok(pg.evaluate("ui.orders.length")==n0, 'Ctrl+Z deshace la última orden')
    # --- sistema de íconos propio (28/10/2026) ---
    bad=pg.evaluate("""async()=>{ const out=[]; for(const n of Object.keys(ICONS)){ const img=new Image(); const ok=await new Promise(r=>{ img.onload=()=>r(1); img.onerror=()=>r(0); img.src=iconURI(n).slice(5,-2); }); if(!ok) out.push(n); } return out; }""")
    ok(bad==[], 'los '+str(pg.evaluate("Object.keys(ICONS).length"))+' íconos propios son SVG válidos y cargan'+(' (fallan: '+', '.join(bad)+')' if bad else ''))
    ok(pg.evaluate("Object.values(EMOJI_ICON).every(n=>ICONS[n])"), 'cada emoji traducido tiene su ícono')
    pg.evaluate("ui.sel=myCapital(); ui.tab='zona'; ui.zsub='resumen'; render()"); pg.wait_for_timeout(150)
    ok(pg.evaluate("document.querySelectorAll('.tabs .ic').length")==7 and pg.evaluate("document.querySelectorAll('.vmode .ic').length")==2, 'las pestañas y los botones de vista usan los íconos propios')
    ok(pg.evaluate("document.querySelectorAll('#tabBody .ic').length")>=4 and pg.evaluate("!/🌾|⚒|🪙|🔬/.test(document.getElementById('tabBody').innerText)"), 'el panel muestra íconos propios en lugar de emoji del sistema')
    ok(len(errs) == 0, 'sin errores de JavaScript: ' + '; '.join(errs[:3]))
    b.close()
srv.shutdown()
sys.exit(1 if fallos else 0)
